theorem log_sum_product_eq_21000 : 
    let n := 20; m := 100; 
        a (k : ℕ) := Real.logb ((5 : ℝ) ^ k) ((3 : ℝ) ^ (k ^ 2)); 
        b (k : ℕ) := Real.logb ((9 : ℝ) ^ k) ((25 : ℝ) ^ k) in
    (∑ k in Finset.Icc 1 n, a k) * (∑ k in Finset.Icc 1 m, b k) = (21000 : ℝ) := sorry

theorem cubic_with_cos_roots : 
    let P : ℝ → ℝ := fun x => x^3 + a * x^2 + b * x + c
    let r1 := Real.cos (2 * π / 7)
    let r2 := Real.cos (4 * π / 7)
    let r3 := Real.cos (6 * π / 7) in
    (∀ x, P x = (x - r1) * (x - r2) * (x - r3)) → a * b * c = 1/32 := sorry

theorem greatest_distance_between_sets :
    let A : Set ℂ := {z | z ^ 3 - 8 = 0}
    let B : Set ℂ := {z | z ^ 3 - 8 * z ^ 2 - 8 * z + 64 = 0}
    in (Sup ((fun (p : ℂ × ℂ) => Complex.dist p.1 p.2) '' (A ×ˢ B)) : ℝ) = 2 * Real.sqrt 21 := sorry

theorem exists_real_root_product_eq_twenty : ∃ (x : ℝ), (fun (x : ℝ) => x^2 + 18*x + 30) x = 2 * Real.sqrt ((fun (x : ℝ) => x^2 + 18*x + 45) x) ∧
    let roots : Set ℝ := {x : ℝ | (fun (x : ℝ) => x^2 + 18*x + 30) x = 2 * Real.sqrt ((fun (x : ℝ) => x^2 + 18*x + 45) x)}
    in (∏ x in roots.toFinset, x) = (20 : ℝ) := sorry
